mapper.select:
SELECT a.*, v.title AS video_title
FROM user_action a
LEFT JOIN video_info v ON a.target_id = v.video_id
WHERE a.user_id = #{userId}
AND a.action_type = #{actionType}
ORDER BY a.create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

mapper.delete:
DELETE FROM user_action
WHERE user_id = #{userId}
AND target_id = #{targetId}
AND action_type = #{actionType}

DELETE FROM user_action
WHERE action_type = 3
  AND target_id IN (
    SELECT comment_id FROM comment_info
    WHERE video_id = #{videoId}
  )
